const resolveContactAssignee = `-- name: ResolveContactAssignee :one
SELECT a.stytch_member_id AS stytch_member_id
FROM crm.contacts ct
LEFT JOIN crm.companies co
  ON co.id = ct.company_id AND co.organization_id = ct.organization_id
LEFT JOIN organizations.accounts a
  ON a.id = COALESCE(ct.assigned_to, co.owner_account_id)
 AND a.organization_id = ct.organization_id
WHERE ct.id = $1 AND ct.organization_id = $2
LIMIT 1
`

type ResolveContactAssigneeParams struct {
	ID             int32 `json:"id"`
	OrganizationID int32 `json:"organization_id"`
}

func (q *Queries) ResolveContactAssignee(ctx context.Context, arg ResolveContactAssigneeParams) (pgtype.Text, error) {
	row := q.db.QueryRow(ctx, resolveContactAssignee, arg.ID, arg.OrganizationID)
	var stytch_member_id pgtype.Text
	err := row.Scan(&stytch_member_id)
	return stytch_member_id, err
}

