const updateConversationStatus = `-- name: UpdateConversationStatus :one
UPDATE crm.conversations c
SET
    status = $1,
    updated_at = NOW()
WHERE c.id = $2 AND c.organization_id = $3
  AND (
    NOT $4::boolean
    OR $5::boolean
    OR c.assignee_stytch_member_id = $6::text
    OR EXISTS (
      SELECT 1
      FROM crm.contacts ct
      JOIN crm.companies co ON co.id = ct.company_id AND co.organization_id = ct.organization_id
      JOIN organizations.accounts a ON a.id = co.owner_account_id AND a.organization_id = co.organization_id
      WHERE ct.id = c.contact_id AND ct.organization_id = c.organization_id
        AND a.stytch_member_id = $6::text
    )
    OR (c.assignee_stytch_member_id IS NULL AND $7::boolean)
  )
RETURNING id, organization_id, contact_id, status, last_message_at, metadata, created_at, updated_at, channel, assignee_stytch_member_id
`

